function renderInbox(){const f=ui.inboxF||'all';const dec=decisionItems();const news=(S.news||[]);const tagOf=k=>({contract:'계약',offer:'이적',overseas:'이적',scout:'전력',league:'리그',injury:'전력',fin:'구단',sys:'구단',alumni:'구단',n:'구단'})[k]||'구단';
  const items=[...dec.map((x,i)=>({id:'d'+i,tag:'중요',t:x.title,s:x.sub||x.tag,when:'지금',on:x.on,pid:x.face?x.face.id:null,hot:true})),...news.map((x,i)=>({id:'n'+i,tag:tagOf(x.kind),t:String(x.text).replace(/<[^>]+>/g,''),when:x.d==null?'':(String(x.d).startsWith('OFF')?String(x.d).replace('OFF','')+'주차':x.d+'일차'),kind:x.kind}))];
  const L=items.filter(x=>f==='all'||(f==='hot'&&x.hot)||(f==='con'&&(x.tag==='계약'||x.tag==='이적'))||(f==='club'&&x.tag==='구단'));const sel=ui.inboxSel&&L.find(x=>x.id===ui.inboxSel)||L[0];
  let h=`<div class="mkh"><button class="bk" onclick="UI.go('home','main')">‹</button><span class="t">감독실 › 수신함</span><span class="r">✉ 미확인 <b class="badge">${dec.length}</b></span></div>`;
  h+=`<div class="mktabs4">${[['all',`수신함(${items.length})`],['hot','중요'],['con','계약/이적'],['club','구단 소식']].map(x=>`<button class="${f===x[0]?'on':''}" onclick="UI.inboxF('${x[0]}')">${x[1]}</button>`).join('')}</div>`;
  h+=`<div class="mkcard" style="padding:0"><table class="mkt inbox"><thead><tr><th>상태</th><th class="tn">제목</th><th class="tr">날짜 ▾</th></tr></thead><tbody>${L.slice(0,14).map(x=>`<tr class="${sel&&sel.id===x.id?'sel':''}" onclick="UI.inboxSel('${x.id}')"><td class="tc"><span class="env ${x.hot?'hot':''}">✉</span></td><td class="tn"><span class="tg ${x.tag==='중요'?'hot':''}">${x.tag}</span> ${esc(x.t.slice(0,40))}</td><td class="tr muted">${esc(x.when)}</td></tr>`).join('')||'<tr><td colspan="3" class="muted">없음</td></tr>'}</tbody></table></div>`;
  if(sel){const p=sel.pid?S.players[sel.pid]:null;h+=`<div class="mkcard"><div class="row" style="gap:8px;align-items:center;margin-bottom:8px"><span class="tg ${sel.hot?'hot':''}">${sel.tag}</span><b style="font-size:17px;flex:1">${esc(sel.t.slice(0,60))}</b><span class="muted small">${esc(sel.when)}</span></div>${p?`<div class="row" style="gap:12px;align-items:center">${face(p,64)}<div><div style="font-size:20px;font-weight:800">${esc(p.name)}</div><div class="small muted">${p.pos} | ${p.bats==='L'?'좌타':'우타'}${p.throws==='L'?'좌투':'우투'} | ${p.age}세</div></div><div class="grow"></div><div class="small" style="text-align:right">${esc(seasonLine(p))}</div></div>`:''}${sel.s?`<div class="quote">“ ${esc(sel.s)}</div>`:''}${sel.on?`<div class="mkbtn2" style="margin-top:10px"><button class="primary big" onclick="${sel.on}">바로 가기</button></div>`:''}</div>`;}
  return h;}
