function squadList(ut){const f=ui.sqf=ui.sqf||{grp:'E',kind:'P',role:'all',gr:'all',sort:'ovr',dir:'desc'};const cap=SL.entryCap(ut);const e=new Set(ut.entry);const two=ut.roster.filter(id=>!e.has(id)).concat(ut.dev);
  let ps=(f.grp==='E'?ut.entry:f.grp==='R'?two:ut.loaned||[]).map(id=>S.players[id]).filter(Boolean);const nP=ps.filter(SL.isPitcher).length,nB=ps.length-nP;ps=ps.filter(p=>f.kind==='P'?SL.isPitcher(p):!SL.isPitcher(p));
  if(f.role!=='all')ps=ps.filter(p=>f.kind==='P'?(f.role==='SP'?ut.rotation.includes(p.id):f.role==='CL'?ut.closer===p.id:f.role==='RP'?(ut.bullpen.includes(p.id)&&ut.closer!==p.id):true):(f.role==='ST'?ut.lineup.includes(p.id):!ut.lineup.includes(p.id)));if(f.gr!=='all')ps=ps.filter(p=>SL.gradeOf(SL.calcOvr(p))===f.gr);
  const sk={ovr:p=>SL.calcOvr(p),age:p=>p.age,cond:p=>condPct(p),pot:p=>p.scout.est,sal:p=>p.contract?p.contract.salary:0}[f.sort]||(p=>SL.calcOvr(p));ps.sort((a,b)=>(sk(b)-sk(a))*(f.dir==='desc'?1:-1));
  const sel=ui.selPid!=null&&ps.some(p=>p.id===ui.selPid)?S.players[ui.selPid]:null;const isP=f.kind==='P';const two2=f.grp==='R';
  let h=`<div class="grptab"><button class="${f.grp==='E'?'on':''}" onclick="UI.sqf('grp','E')">1군 ${ut.entry.length}/${cap}</button><button class="${f.grp==='R'?'on':''}" onclick="UI.sqf('grp','R')">2군 ${two.length}${ut.dev.length?` <small>(육성 ${ut.dev.length})</small>`:''}</button>${(ut.loaned||[]).length?`<button class="${f.grp==='L'?'on':''}" onclick="UI.sqf('grp','L')">임대 ${ut.loaned.length}</button>`:''}</div>`;
  h+=`<div class="mktabs2"><button class="${isP?'on':''}" onclick="UI.sqf('kind','P')">투수 (${nP})</button><button class="${!isP?'on':''}" onclick="UI.sqf('kind','B')">타자 (${nB})</button></div>`;
  h+=`<div class="mkfilt"><select class="sm" onchange="UI.sqf('role',this.value)">${(isP?[['all','전체'],['SP','선발'],['CL','마무리'],['RP','불펜']]:[['all','전체'],['ST','주전'],['BN','벤치']]).map(x=>`<option value="${x[0]}" ${f.role===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><select class="sm" onchange="UI.sqf('gr',this.value)"><option value="all">능력치</option>${['S','A','B','C','D'].map(g=>`<option ${f.gr===g?'selected':''}>${g}등급</option>`).join('')}</select><span class="sep"></span><span class="lb">정렬</span><select class="sm on" onchange="UI.sqf('sort',this.value)">${[['ovr','종합'],['age','나이'],['cond','컨디션'],['pot','잠재력'],['sal','연봉']].map(x=>`<option value="${x[0]}" ${f.sort===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><button class="sm ghost" onclick="UI.sqf('dir','${f.dir==='desc'?'asc':'desc'}')">${f.dir==='desc'?'내림차순 ▾':'오름차순 ▴'}</button></div>`;
  h+=`<div class="mkcard" style="padding:0"><table class="mkt sq"><thead><tr><th>No.</th><th class="tn">선수명</th><th>포지션</th><th>나이</th><th>능력치 (종합)</th><th>${two2?'2군 기록':S.phase==='season'?'컨디션':'지난 시즌'}</th></tr></thead><tbody>${ps.map(p=>`<tr class="${sel&&sel.id===p.id?'sel':''}" onclick="UI.selRow(${p.id})"><td class="tc">${SL.jerseyOf(p)||''}</td><td class="tn"><span class="tfn">${face(p,30)}<b>${esc(p.name)}</b></span></td><td class="tc"><span class="ptg ${ut.closer===p.id?'cl':ut.rotation.includes(p.id)?'sp':''}">${mkTag(p)}</span></td><td class="tc">${p.age}</td><td class="tc">${gradeNum(p)}</td><td class="tc">${two2?(hasSt(p.res)?statShort(p,p.res):'-'):S.phase==='season'?condHtml(p):`<span class="tcl">${seasonLine(p)}</span>`}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">선수가 없습니다.</td></tr>'}</tbody></table></div>`;
  const pid=sel?sel.id:null;const inE=sel&&SL.inEntry(ut,sel.id);h+=`<div class="mkbtn3"><button class="primary" ${pid?'':'disabled'} onclick="UI.openPlayer(${pid})">📋 상세</button><button ${pid?'':'disabled'} onclick="${sel&&SL.isPitcher(sel)?`UI.go('roster','pitch')`:`UI.slotPick(${pid})`}">👥 ${sel&&!SL.isPitcher(sel)?'라인업':'보직'}</button><button ${pid?'':'disabled'} onclick="${inE?`UI.entryDown(${pid})`:ut.dev.includes(pid)?`UI.promote(${pid})`:`UI.entryUp(${pid})`}">⇄ ${inE?'2군 이동':'1군 등록'}</button><button class="ghost" ${pid?'':'disabled'} aria-label="더보기" onclick="UI.pmenu(${pid})">⋯</button></div>`;
  return h;}
