  h+=`<div class="mktabs4">${[['overview','개요'],['ability','능력'],['record','기록'],['contract','계약']].map(x=>`<button class="${tab===x[0]?'on':''}" onclick="UI.pTab('${x[0]}')">${x[1]}</button>`).join('')}</div>`;
  if(tab!=='overview'){const inner=renderPlayer0(Object.assign({},v,{tab}));const i=inner.indexOf('<div class="seg" role="tablist">');const j=inner.indexOf('</div>',i)+6;return h+(i>=0?inner.slice(j):inner);}
  const st=lastSt(p);const sl=st?SL.statLine(p,st.st):null;const keys=isP?['stuff','control','stamina','velo','movement','defense']:['contact','power','eye','speed','defense','arm'];const KO={velo:'구속'};
  const bar=k=>{const v=k==='velo'?Math.round((SL.velocity(p)-120)*3):Math.round(p.attrs[k]||0);const r=hid?SL.attrRange(p,k==='velo'?'stuff':k):null;return `<div class="arow2"><span>${KO[k]||SL.ATTR_KO[k]}</span>${mkBar(hid?(r?(r.lo+r.hi)/2:0):v,100)}<b>${hid?(r?r.lo+'~'+r.hi:'?'):v}</b></div>`;};
  const HW=hw(p);
  h+=`<div class="mkcard"><div class="kv2"><div><span class="k">역할</span><b>${p.loan?loanChip(p):esc(mine?roleTxt:isP?(p.pos==='SP'?'선발 후보':'불펜'):'야수')}</b></div><div><span class="k">포지션</span><b>${p.pos}</b></div></div>
    ${sl?`<div class="stline"><span class="k">최근 시즌<br><small>(${st.label.replace('이번 ','').replace('지난 ','')})</small></span>${isP?`<div><b>${sl.w}승 ${sl.l}패</b></div><div><small>ERA</small><b>${sl.era}</b></div><div><b>${sl.ip}이닝</b></div>`:`<div><small>타율</small><b>${sl.avg}</b></div><div><b>${sl.hr}홈런</b></div><div><b>${sl.rbi}타점</b></div>`}</div>`:''}</div>`;
  h+=`<div class="sg2"><div class="mkcard"><div class="mkhd">주요 능력치 (100)</div>${keys.map(bar).join('')}</div><div class="mkcard"><div class="mkhd">기본 정보</div><table class="kvt"><tr><td>투타</td><td>${p.throws==='L'?'좌투':'우투'}${p.bats==='S'?'양타':p.bats==='L'?'좌타':'우타'}</td></tr><tr><td>신장 / 체중</td><td>${HW.h}cm / ${HW.w}kg</td></tr><tr><td>소속</td><td>${t?esc(t.name):'FA'}</td></tr><tr><td>계약</td><td>${p.contract?`<b>${p.contract.years}년</b> (${mkYear()}~${mkYear()+Math.max(0,p.contract.years-1)})`:'-'}</td></tr><tr><td>연봉</td><td><b>${p.contract?Ms(p.contract.salary):'-'}</b></td></tr></table></div></div>`;
  const hist=(p.hist||[]).slice(-3).reverse();if(hist.length)h+=`<div class="mkcard"><div class="mkhd">주요 경력</div><table class="mkt"><thead><tr><th>시즌</th><th class="tn">소속</th>${isP?'<th>등판</th><th>승</th><th>패</th><th>ERA</th><th>이닝</th>':'<th>경기</th><th>타율</th><th>홈런</th><th>타점</th><th>OPS</th>'}</tr></thead><tbody>${hist.map(x=>{const s=SL.statLine(p,x.st);const T=x.team!=null?S.teams[x.team]:null;return `<tr><td>${mkYear(x.s)}</td><td class="tn"><span class="tfn">${T?emblem(T,18):''}${esc(x.tn)}</span></td>${isP?`<td class="tc">${s.g}</td><td class="tc">${s.w}</td><td class="tc">${s.l}</td><td class="tc">${s.era}</td><td class="tc">${s.ip}</td>`:`<td class="tc">${s.g}</td><td class="tc">${s.avg}</td><td class="tc">${s.hr}</td><td class="tc">${s.rbi}</td><td class="tc">${s.ops}</td>`}</tr>`;}).join('')}</tbody></table></div>`;
  if(hid)h+=scoutCard(p);
