  const n=D.n||SL.krTeams().length;const idx=D.idx;const round=Math.floor(idx/n)+1;const cur=S.teams[D.order[idx]];const myTurn=SL.draftTurn();const mySlots=D.order.map((t,i)=>t===ut.id?i:-1).filter(i=>i>=idx);const nextMine=mySlots[0];const nextT=D.order[idx+1]!=null?S.teams[D.order[idx+1]]:null;
