function renderTable(v){const p=S.players[v.pid];const ut=SL.userTeam();if(!p)return '';const neg=S.market.negs.find(n=>n.pid===v.pid);const done=v.result;const fromT=v.fromTeam!=null?S.teams[v.fromTeam]:null;const stage=neg?neg.stage:'done';
  if(!neg||stage==='club'||(neg&&neg.mode==='renew'))return renderTable0(v);
  const f=ui.form;const F=SL.faM(p.id);const isFA=p.teamId==null;const I=ut.league==='KR'?SL.budgetInfo():null;const st=lastSt(p);const sl=st?SL.statLine(p,st.st):null;const isP=SL.isPitcher(p);const b=SL.bdOf(p);
  const wantY=F?F.ask.yrs:(neg.yrsAsk||(p.age>=32?1:2)),wantS=F?F.ask.sal:(neg.revealed||Math.round((neg.hint[0]+neg.hint[1])/2)),wantB=F?F.ask.bonus:(neg.bonusAsk||0);const tot=(f.salary||0)*(f.years||1)+(f.bonus||0);const prevT=(p.transfers||[]).slice(-1)[0];
  const ev=SL.calcOvr(p)>=SL.BAL.LEVEL_OVR.KR1+6?'최상급':SL.calcOvr(p)>=SL.BAL.LEVEL_OVR.KR1+1?'상위급':SL.calcOvr(p)>=SL.BAL.LEVEL_OVR.KR1-4?'중간급':'보강 자원';const roleT=roleCmp(p).split(' (')[0];
  let h=`<div class="pv tbl3"><div class="pvbar gut"><button aria-label="뒤로" onclick="UI.back()">‹</button><span class="t">${isFA?'FA 협상':'영입 협상'}</span><span class="small" style="margin-left:auto;color:var(--on-navy-dim)">남은 제시 ${neg.maxRounds-neg.rounds}회</span></div><div class="content gut" style="padding-bottom:16px">`;
  h+=`<div class="row" style="gap:12px;align-items:flex-start">${face(p,88)}<div class="grow"><div style="font-size:22px;font-weight:800">${esc(p.name)} <small class="ptg">${p.pos}</small></div><div class="small muted">${p.pos} <span class="sep">|</span> ${p.throws==='L'?'좌투':'우투'}${p.bats==='L'?'좌타':'우타'} <span class="sep">|</span> ${p.age}세 (${mkYear()-p.age}.${String(b.m).padStart(2,'0')}.${String(b.d).padStart(2,'0')})</div><div style="margin-top:6px"><span class="chip o">${esc(roleT)}</span></div></div><table class="kvt right"><tr><td>${isFA?'FA 자격':'소속'}</td><td class="o"><b>${isFA?'획득':esc(fromT?fromT.name:'')}</b></td></tr><tr><td>이전 소속</td><td>${esc(prevT?prevT.from:'-')}</td></tr><tr><td>시장 평가</td><td><b>${ev}</b></td></tr></table></div>`;
  if(sl)h+=`<div class="statrow"><span class="k">${st.label.includes('이번')?mkYear():mkYear(S.season)}시즌<br><small>성적 (정규)</small></span>${(isP?[['등판',sl.g],['선발',sl.gs],['승-패',sl.w+'-'+sl.l],['평균자책점',sl.era],['이닝',sl.ip],['탈삼진',sl.so],['WHIP',(()=>{const x=st.st;return x.pOuts?((x.pH+x.pBB)/(x.pOuts/3)).toFixed(2):'-';})()]]:[['경기',sl.g],['타율',sl.avg],['홈런',sl.hr],['타점',sl.rbi],['OPS',sl.ops],['도루',sl.sb],['볼넷',sl.bb]]).map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div>`;
  h+=`<div class="mkcard">${mkSec('계약 조건 협상')}<div class="negg"><div class="want"><div class="hd2">희망 조건 <small>(선수 측)</small></div><div class="kv"><span>계약 기간</span><b>${wantY}년</b></div><div class="kv"><span>연봉 (연)</span><b>${Ms(wantS)}</b></div><div class="kv"><span>계약금 (보너스)</span><b>${Ms(wantB)}</b></div></div><div class="offer"><div class="hd2 o">제안 조건 <small>(${esc(ut.name)})</small></div><div class="kv"><span>계약 기간</span><span class="stp"><b>${f.years}년</b><button onclick="UI.setF('years',${Math.max(1,f.years-1)})">−</button><button onclick="UI.setF('years',${Math.min(neg.fgn1?1:4,f.years+1)})">+</button></span></div><div class="kv"><span>연봉 (연)</span><span class="stp"><input id="tf_sal" type="number" value="${f.salary}" onchange="UI.setF('salary',+this.value)"><button onclick="UI.bump('salary',-${Math.max(100,Math.round(wantS*0.04/100)*100)})">−</button><button onclick="UI.bump('salary',${Math.max(100,Math.round(wantS*0.04/100)*100)})">+</button></span></div><div class="kv"><span>계약금<br>(보너스)</span><span class="stp"><input id="tf_bonus" type="number" value="${f.bonus}" onchange="UI.setF('bonus',+this.value)"><button onclick="UI.bump('bonus',-${Math.max(100,Math.round(wantS*0.1/100)*100)})">−</button><button onclick="UI.bump('bonus',${Math.max(100,Math.round(wantS*0.1/100)*100)})">+</button></span></div></div></div>
    <div class="row wrap" style="gap:6px;margin-top:8px"><button class="sm ghost" onclick="UI.setF('salary',${wantS});UI.setF('bonus',${wantB});UI.setF('years',${wantY})">요구대로</button><button class="sm ghost" onclick="UI.setF('salary',${Math.round(wantS*0.95/10)*10})">연봉 −5%</button><button class="sm ghost" onclick="UI.setF('salary',${Math.round(wantS*1.05/10)*10})">연봉 +5%</button>${neg.wantPromise?`<label class="sm toggle"><input type="checkbox" ${f.promise?'checked':''} onchange="UI.setF('promise',this.checked)"> 주전 약속</label>`:''}</div>
    <div class="totbox"><span>총 보장액 <small>(계약기간 ${f.years}년, 보너스 포함)</small></span><b>${Ms(tot)}</b></div><div class="sg2"><div class="kvbox"><span>내년 지급액 <small>(${mkYear()+1}시즌)</small></span><b class="o">${Ms((f.salary||0)+(f.bonus||0))}</b></div><div class="kvbox"><span>계약 후 잔여 예산</span><b class="${I&&I.wageLeft-(f.salary||0)<0?'bad':'ok'}">${I?Ms(I.wageLeft-(f.salary||0)):Ms(ut.cash-(f.bonus||0))}</b></div></div>${F&&F.bids.length?`<div class="small muted" style="margin-top:6px">경쟁 제시: ${F.bids.slice(0,3).map(x=>`${esc(S.teams[x.team].name)} ${x.yrs}년 ${Ms(SL.faOfferTot(x))}`).join(' · ')} · ${F.dec}주차 끝 결정</div>`:''}</div>`;
  const keys=isP?['stuff','control','movement','mental','stamina']:['contact','power','eye','speed','defense'];const KO2={mental:'멘탈'};const a20=k=>Math.round((k==='mental'?(p.attrs.clutch||p.attrs.mental||60):p.attrs[k])/5);
  h+=`<div class="mkcard">${mkSec('선수 정보')}<div class="sg2"><table class="kvt"><tr><td>포지션</td><td>${p.pos} (${MK_POS[p.pos]||p.pos})</td></tr><tr><td>역할 예상</td><td>${esc(roleT)}</td></tr><tr><td>나이</td><td>${p.age}세</td></tr><tr><td>투타</td><td>${p.throws==='L'?'좌투':'우투'}${p.bats==='L'?'좌타':'우타'}</td></tr><tr><td>유형</td><td>${esc(SL.diagnose(p).arch)}</td></tr></table><div class="abox"><div class="small b">주요 능력치 (20점 만점)</div>${keys.map(k=>`<div class="arow2"><span>${KO2[k]||SL.ATTR_KO[k]||k}</span>${mkBar(a20(k),20,'g')}<b>${a20(k)}</b></div>`).join('')}</div></div></div>`;
  h+=`<details class="fbox" ${neg.log.length>1?'open':''}><summary>협상 대화 (${neg.log.length})</summary><div class="chat" id="chat">${bubbles(neg.log,{player:p.name,agent:neg.agent?neg.agent+' (대리인)':p.name,club:fromT?fromT.name:'구단'})}</div></details>`;
  h+=mkBtn2(`<button class="ghost big" onclick="UI.leaveTable()">협상 중단</button>`,`<button class="primary big" onclick="UI.tableSubmit()">제안 보내기</button>`);
  return h+`</div></div>`;}
