function renderTrainMock(ut){const ti=ut.trainInt||'normal';const f=ui.trKind||'all';let ps=ut.roster.concat(ut.dev).map(id=>S.players[id]).filter(Boolean);if(f==='young')ps=ps.filter(p=>p.age<=25);else if(f==='P')ps=ps.filter(SL.isPitcher);else if(f==='B')ps=ps.filter(p=>!SL.isPitcher(p));ps.sort((a,b)=>a.age-b.age);
  const sel=ui.selPid!=null&&ps.find(p=>p.id===ui.selPid)||ps[0];const wk=S.phase==='season'?Math.ceil(S.day/7):S.week;const d=mkDate();
  const exp=p=>{const r=SL.report(p);const dg=SL.diagnose(p);const base=p.age<=24?2:p.age<=28?1:0;const v=r&&r.d?Math.round(r.d):base;return v;};
  let h=`<div class="mkh"><span class="t">육성 - 훈련</span><span class="r small">📅 ${wk}주차 (${d.m}/${d.d}~)</span></div>`;
  h+=`<div class="mkcard">${mkSec('주간 훈련 설정','선수별 훈련을 배정하고, 주간 육성 변화를 확인합니다.')}<div class="tibox"><span class="k">훈련 강도 <small>(팀 공통)</small></span><div class="mktabs3">${[['light','가볍게'],['normal','보통'],['hard','집중']].map(x=>`<button class="${ti===x[0]?'on':''}" onclick="UI.trainInt('${x[0]}')">${x[1]}</button>`).join('')}</div><div class="small" style="margin-top:6px">${ti==='hard'?'<span class="ok">▲ 훈련 효과 +15%</span> <span class="sep">|</span> <span class="o">▲ 피로 회복 −3/일</span>':ti==='light'?'<span class="o">▼ 훈련 효과 −15%</span> <span class="sep">|</span> <span class="ok">▲ 피로 회복 +2/일</span>':'훈련 효과 기본 <span class="sep">|</span> 피로 회복 기본'}</div></div></div>`;
  h+=`<div class="row" style="gap:6px;margin-bottom:6px">${[['all','전체'],['young','25세 이하'],['P','투수'],['B','야수']].map(x=>`<button class="sm ${f===x[0]?'primary':'ghost'}" onclick="UI.set('trKind','${x[0]}')">${x[1]}</button>`).join('')}</div>`;
  h+=`<div class="mkcard" style="padding:0"><table class="mkt sq"><thead><tr><th>선수</th><th class="tn">이름</th><th>집중 훈련</th><th>변화(예상)</th><th>피로</th></tr></thead><tbody>${ps.slice(0,ui.trN||14).map(p=>{const F=SL.isPitcher(p)?SL.FOCUS_PIT:SL.FOCUS_BAT;const e=exp(p);return `<tr class="${sel&&sel.id===p.id?'sel':''}" onclick="UI.selRow(${p.id})"><td class="tc"><span class="tfn">${face(p,30)}<span class="ptg dk">${MK_POS[p.pos]||p.pos}</span></span></td><td class="tn"><b>${esc(p.name)}</b> <small class="muted">(${p.age})</small></td><td class="tc"><select class="sm" onclick="event.stopPropagation()" onchange="UI.setFocus(${p.id},this.value)">${Object.entries(F).map(([k,v])=>`<option value="${k}" ${(p.focus||'balance')===k?'selected':''}>${v}</option>`).join('')}</select></td><td class="tc"><b class="${e>0?'ok':e<0?'bad':'muted'}">${e>0?'▲ +'+e:e<0?'▼ '+e:'→ ±0'}</b></td><td class="tc">${Math.round(p.fatigue||0)}%</td></tr>`;}).join('')}</tbody></table>${ps.length>(ui.trN||14)?`<button class="ghost" style="width:100%;border-radius:0 0 10px 10px" onclick="UI.set('trN',${(ui.trN||14)+14})">더 보기</button>`:''}</div>`;
  if(sel){const isP=SL.isPitcher(sel);const F=isP?SL.FOCUS_PIT:SL.FOCUS_BAT;const fk=sel.focus&&sel.focus!=='balance'?sel.focus:null;const dg=SL.diagnose(sel);const keys=fk?[fk,...(isP?SL.PIT_KEYS:SL.BAT_KEYS).filter(k=>k!==fk).slice(0,1)]:(isP?SL.PIT_KEYS:SL.BAT_KEYS).slice(0,2);const g=sel.age<=24?3:sel.age<=28?1:0;const stage=sel.age<=23?'성장기':sel.age<=29?'전성기':'노련기';
    h+=`<div class="mkcard"><div class="row" style="gap:12px;align-items:center">${face(sel,64)}<div><b style="font-size:20px">${esc(sel.name)}</b> <small>(${sel.age})</small><div class="small muted">${isP?'투수':'야수'} <span class="sep">|</span> ${sel.throws==='L'?'좌투':'우투'}${sel.bats==='L'?'좌타':'우타'}</div></div><div class="grow"></div><table class="kvt right"><tr><td>성장 유형</td><td class="ok"><b>${esc(dg.arch)}</b></td></tr><tr><td>개발 단계</td><td class="ok"><b>${stage}${sel.devStart!=null?`(${Math.max(1,S.season-((sel.joinSnap&&sel.joinSnap.s)||S.season)+1)}년차)`:''}</b></td></tr></table></div>
      ${mkSec('훈련 상세')}<table class="mkt mini"><thead><tr><th class="tn">능력치</th><th>훈련 전</th><th></th><th class="hl">훈련 후(예상)</th></tr></thead><tbody>${keys.map((k,i)=>{const v=Math.round(sel.attrs[k]);const dlt=i===0&&fk?g:0;return `<tr><td class="tn">${SL.ATTR_KO[k]}</td><td class="tc"><b>${v}</b> ${mkBar(v,100,'g')}</td><td class="tc">▸</td><td class="tc hl"><b>${v+dlt}</b> <span class="${dlt>0?'ok':'muted'}">(${dlt>0?'+'+dlt:'±0'})</span> ${mkBar(v+dlt,100,'g')}</td></tr>`;}).join('')}</tbody></table>
      <div class="goalbox2"><span>🎯 훈련 목표</span><b>${fk?`${SL.ATTR_KO[fk]} +${Math.max(1,g)} 이상 (주간)`:'균형 훈련 — 목표를 정하려면 집중 훈련을 고르세요'}</b></div>${mkBtn2('',`<button class="primary big" onclick="UI.trainAssign()">🏋 훈련 배정</button>`)}</div>`;}
  return h;}
// ---------- 육성 > 유망주 (시안 12) ----------
function renderProspectMock(ut){const f=ui.prF=ui.prF||{pos:'all',grp:'all'};const res=new Set(SL.reserveIds(ut));let ps=ut.roster.concat(ut.dev).map(id=>S.players[id]).filter(p=>p&&p.age<=25);if(f.grp==='res')ps=ps.filter(p=>res.has(p.id));else if(f.grp==='dev')ps=ps.filter(p=>ut.dev.includes(p.id));if(f.pos==='P')ps=ps.filter(SL.isPitcher);else if(f.pos==='B')ps=ps.filter(p=>!SL.isPitcher(p));ps.sort((a,b)=>b.scout.est-a.scout.est);
  const prog=p=>{const r=SL.report(p);const d=r?r.d:0;return d>=3?['우수','▲▲','ok']:d>=1.5?['양호','▲','ok']:d>0.4?['개선','▲','ok']:d<-0.5?['하락','▼','bad']:['보통','▶',''];};const sel=ui.selPid!=null&&ps.find(p=>p.id===ui.selPid)||ps[0];
  let h=`<div class="mkh"><span class="t">육성 › 유망주</span></div><div class="row sb" style="margin-bottom:6px"><b>유망주 관찰</b><span class="row" style="gap:6px"><select class="sm" onchange="UI.prF('pos',this.value)">${[['all','전체 포지션'],['P','투수'],['B','야수']].map(x=>`<option value="${x[0]}" ${f.pos===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><select class="sm" onchange="UI.prF('grp',this.value)">${[['all','2군/전체'],['res','2군만'],['dev','육성군']].map(x=>`<option value="${x[0]}" ${f.grp===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></span></div>`;
  h+=`<div class="mkcard" style="padding:0"><table class="mkt sq"><thead><tr><th class="tn">선수</th><th>나이</th><th>포지션</th><th>현재</th><th>잠재</th><th>진행도(관찰)</th></tr></thead><tbody>${ps.slice(0,ui.prN||10).map(p=>{const pr=prog(p);return `<tr class="${sel&&sel.id===p.id?'sel':''}" onclick="UI.selRow(${p.id})"><td class="tn"><span class="tfn">${face(p,30)}<b>${esc(p.name)}</b> <small class="muted">${p.age}</small></span></td><td class="tc">${p.age}</td><td class="tc">${p.pos}</td><td class="tc"><b>${Math.round(SL.calcOvr(p))}</b></td><td class="tc"><b class="o">${SL.potText(p)}</b></td><td class="tc"><b class="${pr[2]}">${pr[0]}</b> <span class="${pr[2]}">${pr[1]}</span></td></tr>`;}).join('')||'<tr><td colspan="6" class="muted">25세 이하 선수가 없습니다.</td></tr>'}</tbody></table>${ps.length>(ui.prN||10)?`<button class="ghost" style="width:100%;border-radius:0 0 10px 10px" onclick="UI.set('prN',${(ui.prN||10)+10})">더 보기</button>`:''}</div>`;
  if(sel){const b=SL.bdOf(sel);const logs=(sel.log||[]).slice(0,8).reverse();const pts=logs.length>=2?logs.map(l=>Math.round(l.ovr)):[Math.round(SL.calcOvr(sel))];const lbls=logs.length>=2?logs.map(l=>String(l.label||'').replace(/^\d+시즌 /,'').slice(0,6)):['지금'];const dg=SL.diagnose(sel);const isP=SL.isPitcher(sel);const rh=(sel.rhist||[]).slice(-5).reverse();
    const mn=Math.min(...pts)-2,mx=Math.max(...pts)+2;const W=300,H=120;const X=i=>20+i*(W-40)/Math.max(1,pts.length-1),Y=v=>H-14-(v-mn)/Math.max(1,mx-mn)*(H-30);
    const chart=`<svg viewBox="0 0 ${W} ${H}" class="gchart">${[0,1,2,3].map(i=>`<line x1="20" x2="${W-10}" y1="${H-14-i*(H-30)/3}" y2="${H-14-i*(H-30)/3}" stroke="#ddd"/>`).join('')}<path d="M${pts.map((v,i)=>`${X(i)},${Y(v)}`).join(' L')} L${X(pts.length-1)},${H-14} L20,${H-14}Z" fill="rgba(46,139,79,.18)"/><path d="M${pts.map((v,i)=>`${X(i)},${Y(v)}`).join(' L')}" fill="none" stroke="#2e8b4f" stroke-width="2"/>${pts.map((v,i)=>`<circle cx="${X(i)}" cy="${Y(v)}" r="3.5" fill="#fff" stroke="#2e8b4f" stroke-width="2"/><text x="${X(i)}" y="${Y(v)-7}" font-size="10" text-anchor="middle" fill="#2e8b4f" font-weight="700">${v}</text><text x="${X(i)}" y="${H-2}" font-size="9" text-anchor="middle" fill="#777">${esc(lbls[i])}</text>`).join('')}</svg>`;
    const advice=dg.weak?[`${SL.ATTR_KO[dg.best]||dg.bestTxt}은 안정적`,`${SL.ATTR_KO[dg.weak]} 보완 필요 — 훈련 방향 「${SL.ATTR_KO[dg.weak]}」 권장`,res.has(sel.id)?'당분간 2군에서 실전 경험 누적 권장':'1군 출장 시간 유지']:[`${dg.bestTxt} 안정적`,'뚜렷한 약점 없음',res.has(sel.id)?'콜업 검토 가능':'주전 유지'];
    h+=`<div class="mkcard"><div class="row" style="gap:12px;align-items:center">${face(sel,72)}<div><b style="font-size:22px">${esc(sel.name)}</b> <small>${sel.age}</small> <span class="ptg sp">${sel.pos}</span><div class="small muted">${isP?'투수':'야수'}(${sel.throws==='L'?'좌투':'우투'}${sel.bats==='L'?'좌타':'우타'}) <span class="sep">|</span> ${sel.age}세(${mkYear()-sel.age}.${String(b.m).padStart(2,'0')}.${String(b.d).padStart(2,'0')})</div></div><div class="grow"></div><div class="bb2"><div><small>현재 능력</small><b>${Math.round(SL.calcOvr(sel))}</b></div><div class="o"><small>잠재 능력</small><b>${SL.potText(sel)}</b></div></div></div>
      ${mkSec('육성 진행도',`최근 ${pts.length}회 점검`)}${chart}
      <div class="sg2"><div>${mkSec('2군 시즌 성적','최근')}<table class="mkt mini"><thead><tr><th>시즌</th>${isP?'<th>경기</th><th>이닝</th><th>ERA</th><th>탈삼진</th>':'<th>경기</th><th>타율</th><th>홈런</th><th>타점</th>'}</tr></thead><tbody>${(hasSt(sel.res)?[{s:S.season,st:sel.res}]:[]).concat(rh).slice(0,5).map(x=>{const s=SL.statLine(sel,x.st);return `<tr><td>${mkYear(x.s)}</td>${isP?`<td>${s.g}</td><td>${s.ip}</td><td>${s.era}</td><td>${s.so}</td>`:`<td>${s.g}</td><td>${s.avg}</td><td>${s.hr}</td><td>${s.rbi}</td>`}</tr>`;}).join('')||'<tr><td colspan="5" class="muted">2군 기록 없음</td></tr>'}</tbody></table></div><div>${mkSec('조언')}<div class="advbox"><b>✅ ${res.has(sel.id)?'2군 '+(isP?'선발':'주전')+' 유지':'1군 기용 유지'}</b><ul>${advice.map(a=>`<li>${esc(a)}</li>`).join('')}</ul></div><button class="primary big" onclick="UI.openPlayer(${sel.id})">📈 육성 계획 ›</button></div></div></div>`;}
  return h;}
function renderDev(embed){const ut=SL.userTeam();if(embed)return renderDev0(true);let h=hubTabs('dev');if(!DEV_SUBS.includes(ui.sub.dev))ui.sub.dev='train';if(ui.sub.dev==='train')return h+renderTrainMock(ut);if(ui.sub.dev==='res'){const r=renderReserve(ut);const i=r.indexOf('<div class="grptab">');const j=i>=0?r.indexOf('<div class="mkbtn3">',i):-1;const k=j>=0?r.indexOf('</div>',j)+6:-1;const rest=i>=0&&k>0?r.slice(0,i)+r.slice(k):r;return h+rest+renderProspectMock(ut)+mkBtn2(`<button class="ghost big" onclick="UI.go('league','fut')">🏟 2군 리그 순위·결과</button>`,`<button class="ghost big" onclick="UI.go('roster','list');UI.sqf('grp','R')">👥 2군 명단</button>`);}const inner=renderDev0(false);return inner;}
