function renderFacMock(ut){const F=SL.BAL.FACILITY;const sel=ui.facSel||'train';const FD={train:['훈련장','🏟','선수 훈련 효과','훈련 성장률','피로 회복'],youth:['유소년 센터','🎓','유소년 후보 수','육성군 정원','유망주 잠재 보너스'],scout:['스카우트 조직','🔭','보고서 정확도','후보 수','해외 스카우트 지식']};const lv=ut.fac[sel];const tot=Object.values(ut.fac).reduce((a,b)=>a+b,0);const score=Math.round(40+tot/15*60);
  const C=SL.careerStages();const nx=C.next;
  let h=`<div class="mkh"><span class="t">🏢 구단 시설과 커리어</span></div><div class="mktabs2 half"><button class="${(ui.facTab||'f')==='f'?'on':''}" onclick="UI.set('facTab','f')">구단 시설</button><button class="${ui.facTab==='c'?'on':''}" onclick="UI.set('facTab','c')">구단 커리어</button></div>`;
  if(ui.facTab==='c'){return h+`<div class="mkcard">${mkSec('구단 커리어',`${C.done}/${C.list.length} 단계`)}<div class="chev">${C.list.map((x,i)=>`<span class="${x.done?'done':nx&&nx.k===x.k?'now':''}">${x.done?'✓ ':''}${esc(x.t)}</span>`).join('')}</div>${nx?`<div class="kvbox" style="margin-top:10px"><span><b class="tg hot">다음 목표</b> <b class="o">${esc(nx.t)}</b></span>${nx.need>1?`<span>${nx.cur}/${nx.need}</span>`:''}</div><div class="row" style="gap:8px;align-items:center;margin-top:6px"><span class="small">목표 진행률</span>${mkBar(nx.need>1?nx.cur:0,nx.need>1?nx.need:1,'g')}<b class="ok">${nx.need>1?Math.round(nx.cur/nx.need*100):0}%</b></div>`:'<div class="ok">모든 단계 달성 — 전설</div>'}</div>`+careerCard()+parkCard(ut);}
  h+=`<div class="mkcard">${mkSec('구단 시설 현황',`시설 총평가 <b>${score}</b>`)}<div class="facgrid">${Object.keys(F).map(k=>`<button class="fac ${sel===k?'on':''}" onclick="UI.set('facSel','${k}')"><span class="pic">${FD[k][1]}</span><span class="nm">${FD[k][0]}</span><span class="lv">Lv.${ut.fac[k]}</span></button>`).join('')}<div class="fac dis"><span class="pic">🏥</span><span class="nm">메디컬센터</span><span class="lv">준비 중</span></div><div class="fac dis"><span class="pic">💪</span><span class="nm">체력단련실</span><span class="lv">준비 중</span></div><div class="fac dis"><span class="pic">🛏</span><span class="nm">클럽하우스</span><span class="lv">준비 중</span></div></div></div>`;
  const now=SL.facEffect(sel,lv),nx2=lv<5?SL.facEffect(sel,lv+1):null;
  h+=`<div class="mkcard">${mkSec('시설 개선')}<div class="row" style="gap:12px;align-items:center"><span class="pic big">${FD[sel][1]}</span><div class="grow"><b style="font-size:17px">${FD[sel][0]} 레벨 업</b><div class="row" style="gap:6px;align-items:center;margin:4px 0"><span class="lvb">Lv.${lv}</span>▸<span class="lvb on">Lv.${Math.min(5,lv+1)}</span></div><div class="small">💰 개선 비용 <b class="o">${lv<5?Ms(F[sel].cost*lv):'-'}</b> <span class="sep">|</span> 📅 유지비 ${Ms(F[sel].upkeep*(lv+1))}/시즌</div></div><button class="primary" ${lv>=5?'disabled':''} onclick="UI.upgrade('${sel}')">${lv>=5?'최대':'시설 개선'}</button></div><table class="kvt gray" style="margin-top:8px">${now.map((x,i)=>{const parts=x.split(' ');const cur=parts.slice(1).join(' ');const nv=nx2?nx2[i].split(' ').slice(1).join(' '):'';return `<tr><td>${esc(parts[0])}</td><td class="ok"><b>${esc(nx2?nv:cur)}</b> <small class="muted">(기존 ${esc(cur)})</small></td></tr>`;}).join('')}</table></div>`;
  h+=`<div class="mkcard">${mkSec('구단 커리어')}<div class="chev">${C.list.slice(0,4).map(x=>`<span class="${x.done?'done':nx&&nx.k===x.k?'now':''}">${esc(x.t)}</span>`).join('')}</div>${nx?`<div class="row" style="gap:8px;align-items:center;margin-top:8px"><span class="tg hot">다음 목표</span><b class="o">${esc(nx.t)}</b></div><div class="row" style="gap:8px;align-items:center;margin-top:6px"><span class="small">목표 진행률</span>${mkBar(nx.need>1?nx.cur:0,nx.need>1?nx.need:1,'g')}<b class="ok">${nx.need>1?Math.round(nx.cur/nx.need*100)+'%':'진행 중'}</b></div>`:''}</div>`;
  return h+parkCard(ut);}
